// Stamp _def_path + def_image_reg onto a def JSON so a shape-based locator can
// resolve its template sidecar/pose (defined below; forward-declared for the live
// WS def-load path, which precedes the definition).
static char *def_stamp_context(const char *defJson, const char *defPath);

typedef size_t (*IMG_COMPRESS_FUNC)(uint8_t *dst, size_t dstLen, uint8_t *src, size_t srcLen);

// Downsample src by `downScale` (optionally within an X/Y/W/H crop) into dst.
//   * No calibration needed (no sampler, or sampler does plain pixel fetch):
//     uses cv::resize -- SIMD, and channel-preserving so a mono frame stays
//     CV_8UC1 (1/3 the bytes; the JPEG encoder then gets a true 1-channel image).
//   * Calibration active (lens-distortion remap and/or backlight scaling): keeps
//     the per-pixel calib-aware sampler (cv::resize can't do per-pixel remap).
void ImageDownSampling(cv::Mat &dst, const cv::Mat &src, int downScale,
                       ImageSampler *sampler, int doNearest = 1,
                       int X = -1, int Y = -1, int W = -1, int H = -1)
{
  if (src.empty() || (src.type() != CV_8UC3 && src.type() != CV_8UC1)) return;
  if (downScale < 1) downScale = 1;
  const int srcCn = src.channels();   // 1 (mono gray) or 3 (B=G=R)
  cv::Mat src_c = src.isContinuous() ? src : src.clone();
  int X2 = src_c.cols - 1, Y2 = src_c.rows - 1;
  int xx = (X < 0) ? 0 : (X >= X2 ? X2 - 1 : X);
  int yy = (Y < 0) ? 0 : (Y >= Y2 ? Y2 - 1 : Y);
  if (W > 0) { X2 = xx + W; if (X2 >= src_c.cols)  X2 = src_c.cols - 1;  }
  if (H > 0) { Y2 = yy + H; if (Y2 >= src_c.rows)  Y2 = src_c.rows - 1;  }
  int sxStart = xx / downScale, syStart = yy / downScale;
  int sxEnd   = X2 / downScale, syEnd   = Y2 / downScale;
  int dstW = sxEnd - sxStart + 1;
  int dstH = syEnd - syStart + 1;
  if (dstW < 1 || dstH < 1) return;

  // --- Fast path: plain downsample via OpenCV (no distortion / no backlight) ---
  if (!sampler || sampler->samplingIsIdentity())
  {
    int x0 = sxStart * downScale, y0 = syStart * downScale;
    int roiW = (sxEnd * downScale + downScale) - x0; if (x0 + roiW > src_c.cols) roiW = src_c.cols - x0;
    int roiH = (syEnd * downScale + downScale) - y0; if (y0 + roiH > src_c.rows) roiH = src_c.rows - y0;
    if (roiW < 1) roiW = 1;
    if (roiH < 1) roiH = 1;
    cv::Mat roi = src_c(cv::Rect(x0, y0, roiW, roiH));
    // INTER_AREA gives a clean anti-aliased downscale; INTER_NEAREST matches the
    // old point-sampling when the caller asked for nearest.
    cv::resize(roi, dst, cv::Size(dstW, dstH), 0, 0,
               doNearest ? cv::INTER_NEAREST : cv::INTER_AREA);
    return;
  }

  // --- Calibration-aware path: per-pixel sampler (distortion remap + backlight) ---
  // Output channels follow the source so a mono frame stays CV_8UC1.
  dst.create(dstH, dstW, srcCn == 1 ? CV_8UC1 : CV_8UC3);
  for (int i = syStart; i <= syEnd; i++)
  {
    int src_i = i * downScale;
    uint8_t *dRow = dst.ptr<uint8_t>(i - syStart);
    for (int j = sxStart; j <= sxEnd; j++)
    {
      int src_j = j * downScale;
      float coord[2] = { (float)src_j, (float)src_i };
      if (srcCn == 1)
      {
        float g = sampler->sampleImage1_IdealCoord(src_c, coord, doNearest);  // gray: 1 sample, not 3
        if (g > 255) g = 255;
        dRow[j - sxStart] = (uint8_t)g;
      }
      else
      {
        float bgr[3];
        sampler->sampleImage3_IdealCoord(src_c, coord, bgr, doNearest);
        for (int k = 0; k < 3; k++) if (bgr[k] > 255) bgr[k] = 255;
        uint8_t *dPix = dRow + (j - sxStart) * 3;
        dPix[0] = (uint8_t)bgr[0]; dPix[1] = (uint8_t)bgr[1]; dPix[2] = (uint8_t)bgr[2];
      }
    }
  }
}

cJSON *cJSON_DirFiles(const char *path, cJSON *jObj_to_W, int depth = 0)
{
  if (path == NULL)
    return NULL;

  DIR *d = opendir(path);

  if (d == NULL)
    return NULL;

  cJSON *retObj = (jObj_to_W == NULL) ? cJSON_CreateObject() : jObj_to_W;
  struct dirent *dir;
  cJSON *dirFiles = cJSON_CreateArray();
  char buf[PATH_MAX + 1];
  realfullPath(path, buf);

  cJSON_AddStringToObject(retObj, "path", buf);
  cJSON_AddItemToObject(retObj, "files", dirFiles);

  std::string folderPath(buf);

  if (depth > 0)
    while ((dir = readdir(d)) != NULL)
    {
      //if(dir->d_name[0]=='.')continue;
      cJSON *fileInfo = cJSON_CreateObject();
      cJSON_AddItemToArray(dirFiles, fileInfo);
      cJSON_AddStringToObject(fileInfo, "name", dir->d_name);

      char *type = NULL;
      std::string fileName(dir->d_name);
      std::string filePath = folderPath + "/" + fileName;

      // dirent::d_type isn't filled by mingw-w64's <dirent.h>; portable path
      // is stat() the full file path and dispatch on st_mode.
      struct stat _st;
      int _stat_ok = (stat(filePath.c_str(), &_st) == 0);
      if (_stat_ok && S_ISREG(_st.st_mode))
      {
        type = "REG";
      }
      else if (_stat_ok && S_ISDIR(_st.st_mode))
      {
        if (depth > 0 && dir->d_name != NULL && dir->d_name[0] != '\0' && dir->d_name[0] != '.')
        {
          cJSON *subFolderStruct = cJSON_DirFiles(filePath.c_str(), NULL, depth - 1);
          if (subFolderStruct != NULL)
          {
            cJSON_AddItemToObject(fileInfo, "struct", subFolderStruct);
          }
        }
        type = "DIR";
      }
      else
      {
        type = "UNKNOWN";
      }
      cJSON_AddStringToObject(fileInfo, "type", type);

      struct stat st;
      if (stat(filePath.c_str(), &st) == 0)
      {
        cJSON_AddNumberToObject(fileInfo, "size_bytes", st.st_size);
        cJSON_AddNumberToObject(fileInfo, "mtime_ms", st.st_mtime * 1000);
        cJSON_AddNumberToObject(fileInfo, "ctime_ms", st.st_ctime * 1000);
        cJSON_AddNumberToObject(fileInfo, "atime_ms", st.st_atime * 1000);
      }
    }
  closedir(d);

  return retObj;
}

machine_hash machine_h = {0};
void AttachStaticInfo(cJSON *reportJson, m_BPG_Protocol_Interface *BPG_prot_if)
{
  if (reportJson == NULL)
    return;
  char tmpStr[128];

  {
    char *tmpStr_ptr = tmpStr;
    for (int i = 0; i < sizeof(machine_h.machine); i++)
    {
      tmpStr_ptr += sprintf(tmpStr_ptr, "%02X", machine_h.machine[i]);
    }
    cJSON_AddStringToObject(reportJson, "machine_hash", tmpStr);
  }
}
